var allLabels = $input.all().map(function(item) { return item.json; });
var emailData = $('Gmail Trigger').item.json;
var emailLabelIds = emailData.labelIds || [];
var isClienti = allLabels.some(function(label) {
  return emailLabelIds.includes(label.id) && label.name && label.name.toUpperCase().startsWith('CLIENTI');
});
var isPromotional = emailLabelIds.some(function(id) {
  return ['CATEGORY_PROMOTIONS', 'CATEGORY_SOCIAL'].includes(id);
});
var fromField = emailData.from;
var fromEmail = '';
if (fromField && typeof fromField === 'object' && fromField.value && fromField.value.length > 0) {
  fromEmail = (fromField.value[0].address || '').toLowerCase();
} else if (typeof fromField === 'string') {
  var match = fromField.match(/<([^>]+)>/);
  fromEmail = match ? match[1].toLowerCase() : fromField.toLowerCase();
}
var isSelfEmail = fromEmail === 'attilio.assirelli@gmail.com';
var collaboratorPatterns = [
  { pattern: 'ROSA ASSIRELLI', folder: 'ROSA ASSIRELLI' },
  { pattern: 'NICOLA MAROTTA', folder: 'Nicola Marotta' },
  { pattern: 'FRANCESCO DURANTI', folder: 'Francesco Duranti' },
  { pattern: 'LEGALADVICE', folder: 'LegalAdvice' }
];
var collaborator = null;
allLabels.forEach(function(label) {
  if (emailLabelIds.includes(label.id) && label.name) {
    var upperName = label.name.toUpperCase();
    collaboratorPatterns.forEach(function(cp) {
      if (upperName.includes(cp.pattern)) { collaborator = cp.folder; }
    });
  }
});
return [{ json: {
  isClientiEmail: isClienti, isPromotional: isPromotional, isSelfEmail: isSelfEmail,
  collaborator: collaborator, source: 'email', whatsappFrom: '', phoneNumberId: '',
  id: emailData.id || '', threadId: emailData.threadId || '',
  from: emailData.from || '', to: emailData.to || '',
  subject: emailData.subject || '', snippet: emailData.snippet || '',
  text: emailData.text || '', html: emailData.html || '',
  date: emailData.date || '', labelIds: emailData.labelIds || []
} }];

var items = $input.all();
var rawText = items.length > 0 ? (items[0].json.text || '') : '';
var topic = 'GENERALE';
var driveQuery = '';
var keywords = [];
var parsed = {};
try {
  var cleaned = rawText.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();
  var m = cleaned.match(/\{[\s\S]*\}/);
  if (m) {
    parsed = JSON.parse(m[0]);
    topic = parsed.topic || 'GENERALE';
    if (parsed.keywords && parsed.keywords.length > 0) {
      keywords = parsed.keywords;
      driveQuery = parsed.keywords.map(function(k) {
        return "fullText contains '" + String(k).replace(/'/g, "\\'") + "'";
      }).join(' OR ');
    }
  }
} catch (e) {}
var topicMap = { PAGHE: 'CONSULENTE DEL LAVORO E DELLA PREVIDENZA CLIENTI', DIRITTO_LAVORO: 'DIRITTO DEL LAVORO', PREVIDENZA: 'DIRITTO DELLA PREVIDENZA', INPS: 'INPS', INAIL: 'INAIL', AGGIORNAMENTI: 'AGGIORNAMENTI NORMATIVI', FISCALE_NORMATIVA: 'CONSULENZA FISCALE NORMATIVA', FISCALE_USPPIDA: 'CONSULENZA FISCALE USPPIDA', GENERALE: 'CONSULENTE DEL LAVORO E DELLA PREVIDENZA' };
var driveFolder = topicMap[topic] || topicMap.GENERALE;
if (!driveQuery) { driveQuery = driveFolder; }
var webSearchQuery = (keywords.length > 0 ? keywords.join(' ') : driveFolder) + ' normativa italiana';
var company = '';
var year = null;
var month = null;
try { company = parsed.company || ''; } catch(e) {}
try { year = parsed.year || null; } catch(e) {}
try { month = parsed.month || null; } catch(e) {}
return [{ json: { topic: topic, driveFolder: driveFolder, driveQuery: driveQuery, folderSearchQuery: driveQuery, webSearchQuery: webSearchQuery, company: company, year: year, month: month } }];

var emailData = {};
try { emailData = $('Gmail Trigger').item.json || {}; } catch(e) {}
if (!emailData.id && !emailData.threadId) { try { emailData = $('Normalizza Messaggio WhatsApp').item.json || {}; } catch(e2) {} }
var topic = 'GENERALE';
try { topic = $('Mappa Argomento a Cartella').item.json.topic || 'GENERALE'; } catch(e) {}


// ── Notion — Cliente + Knowledge Base ──────────────────────────────────
var notionClienteInfo = '';
try {
  var nCliente = $('Cerca Cliente in Notion').item.json;
  if (nCliente && nCliente.results && nCliente.results.length > 0) {
    var c = nCliente.results[0].properties;
    var ccnl = (c['CCNL Applicato'] && c['CCNL Applicato'].select) ? c['CCNL Applicato'].select.name : '';
    var nomeRaw = c['Nome / Ragione Sociale'] && c['Nome / Ragione Sociale'].title;
    var nome = nomeRaw ? nomeRaw.map(function(t){return t.plain_text;}).join('') : '';
    if (nome) notionClienteInfo = 'CLIENTE: ' + nome + (ccnl ? ' — CCNL: ' + ccnl : '');
  }
} catch(e) {}

var notionKBInfo = '';
try {
  var nKB = $('Cerca in Knowledge Base').item.json;
  if (nKB && nKB.results && nKB.results.length > 0) {
    var kbLines = nKB.results.slice(0,3).map(function(page, i) {
      var props = page.properties;
      var titoloRaw = props['Titolo'] && props['Titolo'].title;
      var titolo = titoloRaw ? titoloRaw.map(function(t){return t.plain_text;}).join('') : 'Documento';
      var contenutoRaw = props['Contenuto'] && props['Contenuto'].rich_text;
      var contenuto = contenutoRaw ? contenutoRaw.map(function(t){return t.plain_text;}).join('').substring(0,300) : '';
      return (i+1) + '. ' + titolo + (contenuto ? '\n   ' + contenuto : '');
    });
    if (kbLines.length > 0) notionKBInfo = '=== KNOWLEDGE BASE STUDIO ===\n' + kbLines.join('\n\n');
  }
} catch(e) {}

var driveItems = [];
try { driveItems = $('Cerca File Cliente').all(); } catch(e) {}
if (driveItems.length === 0 || !driveItems[0].json.id) {
  try { driveItems = $('Cerca Documenti Drive').all(); } catch(e) {}
}

var googleResults = '';
try {
  var gItems = $('Elabora Risultati Google').all();
  if (gItems.length > 0) googleResults = gItems[0].json.googleResults || '';
} catch(e) {}

var tavilyResults = '';
try {
  var tItems = $('Cerca su Tavily').all();
  if (tItems.length > 0) {
    var tData = tItems[0].json;
    var answer = tData.answer || '';
    var results = tData.results || [];
    if (answer) tavilyResults = 'Risposta sintetica: ' + answer;
    if (results.length > 0) {
      var tLines = results.slice(0, 3).map(function(r, i) {
        return (i+1) + '. ' + (r.title || '') + '\n   ' + String(r.content || '').substring(0, 200) + '\n   ' + (r.url || '');
      });
      tavilyResults += (tavilyResults ? '\n\n' : '') + tLines.join('\n\n');
    }
  }
} catch(e) {}

var webResults = [googleResults, tavilyResults].filter(Boolean).join('\n\n---\n\n');

// ── Legal Data Hunter — Legislazione Italiana ──────────────────────────
var ldhResults = '';
try {
  var ldhItems = $('Cerca Legislazione IT').all();
  if (ldhItems.length > 0 && ldhItems[0].json.hits) {
    var hits = ldhItems[0].json.hits || [];
    if (hits.length > 0) {
      var ldhLines = hits.slice(0, 3).map(function(h, i) {
        return (i+1) + '. ' + (h.title || 'Norma') + '\n'
             + '   ' + String(h.snippet || '').substring(0, 250) + '\n'
             + '   Fonte: ' + (h.url || 'legaldatahunter.com') + (h.date ? ' (' + h.date + ')' : '');
      });
      ldhResults = '=== NORMATIVA ITALIANA RILEVANTE ===\n' + ldhLines.join('\n\n');
    }
  }
} catch(e) {}


var attachmentText = '';
try {
  var pdfData = $('Aggiungi Contesto Allegati').first().json;
  if (pdfData && pdfData.hasPDF && pdfData.attachmentText) {
    attachmentText = String(pdfData.attachmentText);
  }
} catch(e) {}

var driveContext = 'Nessun documento trovato su Google Drive per questa richiesta.';
var validItems = driveItems.filter(function(i) { return i.json && i.json.id; });
if (validItems.length > 0) {
  var lines = validItems.map(function(item, idx) {
    var name = item.json.name || ('Documento ' + (idx + 1));
    var link = item.json.webViewLink ? (' - ' + item.json.webViewLink) : '';
    return (idx + 1) + '. ' + name + link;
  });
  driveContext = 'Documenti trovati (argomento: ' + topic + '):\n' + lines.join('\n');
}
var aggiornamenti = '';
try { aggiornamenti = $('Cerca File Utente').item.json.aggiornamenti || ''; } catch(e) {}
var emailBodyLower = (String(emailData.text || '') + ' ' + String(emailData.subject || '')).toLowerCase();
var attachRequest = /gira|invi[ao]|allega|mand[ae]|spedi/.test(emailBodyLower);
var attachFileId = null;
var attachFileName = null;
if (attachRequest && validItems.length > 0) {
  var pdfItems = validItems.filter(function(i) { var n = (i.json.name || '').toLowerCase(); return !n.includes('f24') && !n.includes('tel-'); });
  var cedolinoItem = pdfItems.find(function(i) { return (i.json.name || '').toLowerCase().includes('cedolino'); });
  var toAttach = cedolinoItem || pdfItems[0] || validItems[0];
  if (toAttach && toAttach.json.id) { attachFileId = toAttach.json.id; attachFileName = toAttach.json.name || 'documento.pdf'; }
}

return [{ json: {
  from: String(emailData.from?.value?.[0]?.address || emailData.from || ''),
  to: String(emailData.to?.value?.[0]?.address || emailData.to || ''),
  subject: String(emailData.subject || ''),
  snippet: String(emailData.snippet || ''),
  text: String(emailData.text || ''),
  threadId: String(emailData.threadId || ''),
  id: String(emailData.id || ''),
  driveContext: driveContext,
  notionCliente: notionClienteInfo,
  notionKB: notionKBInfo,
  topic: topic,
  aggiornamenti: aggiornamenti,
  googleResults: [webResults, ldhResults, notionKBInfo].filter(Boolean).join('\n\n---\n\n'),
  attachmentText: attachmentText,
  attachRequest: attachRequest,
  attachFileId: attachFileId,
  attachFileName: attachFileName
} }];

var items = $input.all();
var aiResponse = items.length > 0 ? (items[0].json.text || '') : '';
var emailData = {};
try { emailData = $('Gmail Trigger').item.json || {}; } catch(e) {}
if (!emailData.id && !emailData.threadId) { try { emailData = $('Normalizza Messaggio WhatsApp').item.json || {}; } catch(e2) {} }
var source = emailData.source || 'email';
return [{ json: {
  aiResponse: String(aiResponse),
  from: String(emailData.from || ''),
  subject: String(emailData.subject || ''),
  threadId: String(emailData.threadId || ''),
  messageId: String(emailData.id || ''),
  source: source,
  whatsappFrom: String(emailData.whatsappFrom || ''),
  phoneNumberId: String(emailData.phoneNumberId || ''),
  attachRequest: Boolean($('Aggrega Contesto').item.json.attachRequest),
  attachFileId: String($('Aggrega Contesto').item.json.attachFileId || ''),
  attachFileName: String($('Aggrega Contesto').item.json.attachFileName || '')
} }];

var monthFolderIds = [];
$input.all().forEach(function(item) {
  if (item.json && item.json.id) {
    monthFolderIds.push(item.json.id);
  }
});
var yearFolderIds = [];
try {
  $('Cerca Cartella Anno').all().forEach(function(item) {
    if (item.json && item.json.id) {
      yearFolderIds.push(item.json.id);
    }
  });
} catch(e) {}
var driveQuery = '';
try { driveQuery = $('Mappa Argomento a Cartella').item.json.driveQuery || ''; } catch(e) {}
var fileQuery;
if (monthFolderIds.length > 0) {
  fileQuery = monthFolderIds.map(function(id) { return "'" + id + "' in parents"; }).join(' OR ');
} else if (yearFolderIds.length > 0) {
  fileQuery = yearFolderIds.map(function(id) { return "'" + id + "' in parents"; }).join(' OR ');
} else {
  var ditaFolderIds = [];
  try {
    $('Cerca Cartella Azienda').all().forEach(function(item) {
      if (item.json && item.json.id) {
        ditaFolderIds.push(item.json.id);
      }
    });
  } catch(e) {}
  if (ditaFolderIds.length > 0) {
    fileQuery = ditaFolderIds.map(function(id) { return "'" + id + "' in parents"; }).join(' OR ');
  } else {
    fileQuery = driveQuery || "trashed = false";
  }
}
var topic = 'GENERALE';
try { topic = $('Mappa Argomento a Cartella').item.json.topic || 'GENERALE'; } catch(e) {}
if (topic === 'PAGHE' && fileQuery && fileQuery !== 'trashed = false') {
  fileQuery = '(' + fileQuery + ") and not name contains 'f24' and not name contains 'TEL-' and mimeType = 'application/pdf'";
}
return [{ json: { monthFolderIds: monthFolderIds, yearFolderIds: yearFolderIds, fileQuery: fileQuery, hasFolders: monthFolderIds.length > 0 || yearFolderIds.length > 0 } }];

var folderItems = $input.all();
var intermediarioIds = [];
folderItems.forEach(function(item) {
  if (item.json && item.json.id) {
    intermediarioIds.push(item.json.id);
  }
});
var company = '';
var collaborator = null;
try {
  var mappaOutput = $('Mappa Argomento a Cartella').item.json;
  company = mappaOutput.company || '';
  collaborator = mappaOutput.collaborator || null;
} catch(e) {}
var companyQuery;
if (company) {
  var companyUpper = company.toUpperCase();
  companyQuery = "mimeType = 'application/vnd.google-apps.folder' and name contains '" + companyUpper.replace(/'/g, "\\'") + "'";
} else if (intermediarioIds.length > 0) {
  companyQuery = "mimeType = 'application/vnd.google-apps.folder' and name contains 'cliente'";
} else {
  companyQuery = "name = '__nessun_risultato__'";
}
return [{ json: { intermediarioIds: intermediarioIds, companyQuery: companyQuery } }];

var ditaFolderIds = [];
$input.all().forEach(function(item) {
  if (item.json && item.json.id) {
    ditaFolderIds.push(item.json.id);
  }
});
var year = null;
try { year = $('Mappa Argomento a Cartella').item.json.year || null; } catch(e) {}
var yearQuery;
if (ditaFolderIds.length > 0 && year) {
  var parentsPart = ditaFolderIds.map(function(id) { return "'" + id + "' in parents"; }).join(' OR ');
  yearQuery = "mimeType = 'application/vnd.google-apps.folder' and (" + parentsPart + ") and name = '" + year + "'";
} else if (ditaFolderIds.length > 0) {
  var parentsPart2 = ditaFolderIds.map(function(id) { return "'" + id + "' in parents"; }).join(' OR ');
  yearQuery = "mimeType = 'application/vnd.google-apps.folder' and (" + parentsPart2 + ") and name contains '202'";
} else {
  yearQuery = "name = '__nessun_risultato__'";
}
return [{ json: { ditaFolderIds: ditaFolderIds, yearQuery: yearQuery, year: year } }];

var topic = 'GENERALE';
var driveQuery = '';
var year = null;
var emailText = '';
var emailSubject = '';
try {
  var mappaOutput = $('Mappa Argomento a Cartella').item.json;
  topic = mappaOutput.topic || 'GENERALE';
  driveQuery = mappaOutput.driveQuery || '';
  year = mappaOutput.year || null;
} catch(e) {}
try {
  var emailData = $('Gmail Trigger').item.json;
  emailText = emailData.text || emailData.snippet || '';
  emailSubject = emailData.subject || '';
} catch(e) {}
var webSearchTopics = ['AGGIORNAMENTI', 'INPS', 'INAIL', 'PREVIDENZA', 'DIRITTO_LAVORO', 'FISCALE_NORMATIVA', 'FISCALE_USPPIDA'];
var needsWebSearch = webSearchTopics.includes(topic);
var normativeKeywords = ['accertamento', 'circolare', 'normativa', 'decreto', 'aggiornamento', 'sentenza', 'contributi', 'previdenz', 'ricerca normativa', 'verifica'];
var emailLower = (emailText + ' ' + emailSubject).toLowerCase();
if (!needsWebSearch) {
  needsWebSearch = normativeKeywords.some(function(kw) { return emailLower.includes(kw); });
}
var searchQuery = '';
if (needsWebSearch) {
  var keyTerms = [];
  if (emailLower.includes('inps')) keyTerms.push('INPS');
  if (emailLower.includes('inail')) keyTerms.push('INAIL');
  if (emailLower.includes('accertamento')) keyTerms.push('accertamento');
  if (emailLower.includes('circolare')) keyTerms.push('circolare ministeriale');
  if (emailLower.includes('cedolino') || emailLower.includes('paga') || topic === 'PAGHE') keyTerms.push('cedolini busta paga');
  if (emailLower.includes('previdenz') || topic === 'PREVIDENZA') keyTerms.push('previdenza sociale');
  if (emailLower.includes('decreto')) keyTerms.push('decreto legge');
  if (emailLower.includes('contratto') || topic === 'DIRITTO_LAVORO') keyTerms.push('contratto di lavoro CCNL');
  if (topic === 'AGGIORNAMENTI') keyTerms.push('aggiornamenti normativi lavoro');
  if (year) keyTerms.push(year);
  if (keyTerms.length === 0) keyTerms.push('normativa lavoro italiana');
  keyTerms.push('Italia');
  searchQuery = keyTerms.join(' ');
}
return [{ json: { needsWebSearch: needsWebSearch, searchQuery: searchQuery } }];

var d = $input.first().json;
var msgType = d.type || '';
if (msgType && msgType !== 'text') return [];
var body = '';
try { body = d.text.body || ''; } catch(e) {}
if (!body && d.body) body = String(d.body);
if (!body) return [];
var from = d.from || d.wa_id || '';
var contactName = '';
try { contactName = d.contacts[0].profile.name || ''; } catch(e) {}
if (!contactName) contactName = from;
var msgId = d.id || '';
var timestamp = d.timestamp ? new Date(parseInt(d.timestamp) * 1000).toISOString() : new Date().toISOString();
var phoneNumberId = '';
try { phoneNumberId = d.metadata.phone_number_id || ''; } catch(e) {}
return [{ json: {
  isClientiEmail: true, isPromotional: false, isSelfEmail: false,
  collaborator: null, source: 'whatsapp',
  id: msgId, threadId: from,
  from: contactName + ' <' + from + '>',
  to: 'WhatsApp Business',
  subject: 'WhatsApp da ' + contactName,
  snippet: body.substring(0, 100), text: body, html: '',
  date: timestamp, labelIds: [],
  whatsappFrom: from, phoneNumberId: phoneNumberId
}}];

var pagheMensiliIds = [];
$input.all().forEach(function(item) {
  if (item.json && item.json.id) {
    pagheMensiliIds.push(item.json.id);
  }
});
var yearFolderIds = [];
try {
  $('Cerca Cartella Anno').all().forEach(function(item) {
    if (item.json && item.json.id) {
      yearFolderIds.push(item.json.id);
    }
  });
} catch(e) {}
var month = null;
try { month = $('Mappa Argomento a Cartella').item.json.month || null; } catch(e) {}
var parentIds = pagheMensiliIds.length > 0 ? pagheMensiliIds : yearFolderIds;
var monthQuery;
if (parentIds.length > 0 && month) {
  var monthUpper = month.toUpperCase();
  var parentsPart = parentIds.map(function(id) { return "'" + id + "' in parents"; }).join(' OR ');
  monthQuery = "mimeType = 'application/vnd.google-apps.folder' and (" + parentsPart + ") and name contains '" + month.toLowerCase() + "'";
} else {
  monthQuery = "name = '__nessun_risultato__'";
}
return [{ json: { pagheMensiliIds: pagheMensiliIds, yearFolderIds: yearFolderIds, monthQuery: monthQuery, month: month } }];

var items = $input.all();
if (items.length > 0 && items[0].json && Object.keys(items[0].json).length > 0) {
  return items;
}
return [{ json: { driveEmpty: true } }];

var items = $input.all();
if (items.length > 0) return items;
return [{ json: {} }];

var items = $input.all();
if (items.length > 0) return items;
return [{ json: {} }];

var items = $input.all();
if (items.length > 0) return items;
return [{ json: {} }];

var items = $input.all();
if (items.length > 0) return items;
return [{ json: {} }];

var yearFolderIds = [];
$input.all().forEach(function(item) {
  if (item.json && item.json.id) {
    yearFolderIds.push(item.json.id);
  }
});
var topic = 'GENERALE';
try { topic = $('Mappa Argomento a Cartella').item.json.topic || 'GENERALE'; } catch(e) {}
var pagheMensiliQuery;
if (topic === 'PAGHE' && yearFolderIds.length > 0) {
  var parentsPart = yearFolderIds.map(function(id) { return "'" + id + "' in parents"; }).join(' OR ');
  pagheMensiliQuery = "mimeType = 'application/vnd.google-apps.folder' and (" + parentsPart + ") and name = '01_PAGHE_MENSILI'";
} else {
  pagheMensiliQuery = "name = '__nessun_risultato__'";
}
return [{ json: { yearFolderIds: yearFolderIds, pagheMensiliQuery: pagheMensiliQuery, topic: topic } }];

var items = $input.all();
if (items.length > 0) return items;
return [{ json: {} }];

var parentFolderId = null;
var source = 'nessuna';
// 1° tentativo: cartella ditta specifica (Cerca Cartella Azienda)
try {
  var aziItems = $('Cerca Cartella Azienda').all();
  var valid = aziItems.filter(function(i) { return i.json && i.json.id; });
  if (valid.length > 0) { parentFolderId = valid[0].json.id; source = 'ditta'; }
} catch(e) {}
// 2° tentativo: cartella intermediario (Cerca Documenti Drive)
if (!parentFolderId) {
  try {
    var driveItems = $('Cerca Documenti Drive').all();
    var validD = driveItems.filter(function(i) { return i.json && i.json.id; });
    if (validD.length > 0) { parentFolderId = validD[0].json.id; source = 'intermediario'; }
  } catch(e) {}
}
if (!parentFolderId) {
  return [{ json: { parentFolderId: null, skip: true, source: 'nessuna',
    searchQuery: "name = '__nessun_risultato__'" } }];
}
var q = "mimeType = 'application/vnd.google-apps.folder' and name = 'Corrispondenza' and '" + parentFolderId + "' in parents and trashed = false";
return [{ json: { parentFolderId: parentFolderId, skip: false, source: source, searchQuery: q } }];

var folderId = null;
// Prova dalla ricerca (cartella già esistente)
try {
  var found = $('Cerca Cartella Corrispondenza').item.json;
  if (found && found.id) folderId = found.id;
} catch(e) {}
// Prova dalla cartella appena creata
if (!folderId) {
  try {
    var created = $('Crea Cartella Corrispondenza').item.json;
    if (created && created.id) folderId = created.id;
  } catch(e) {}
}
if (!folderId) return [];

// Dati email e risposta
var bozza = {};
try { bozza = $('Prepara Bozza').item.json; } catch(e) {}
var subject = bozza.subject || 'Nessun oggetto';
var fromAddr = bozza.from || '';
var aiResponse = bozza.aiResponse || '';

var emailText = '';
try {
  var emailData = $('Gmail Trigger').item.json;
  emailText = emailData.text || emailData.snippet || '';
} catch(e) {}

var dateStr = new Date().toISOString().replace('T', ' ').substring(0, 16);
var dateFile = new Date().toISOString().split('T')[0];

var fileContent = 
  '---\n' +
  'data: ' + dateStr + '\n' +
  'mittente: ' + fromAddr + '\n' +
  'oggetto: "' + subject.replace(/"/g, '\\"') + '"\n' +
  'tag:\n' +
  '  - corrispondenza\n' +
  '  - email\n' +
  '---\n\n' +
  '# ' + subject + '\n\n' +
  '- **Data:** ' + dateStr + '\n' +
  '- **Mittente:** ' + fromAddr + '\n\n' +
  '---\n\n' +
  '## ✉️ Email Ricevuta\n' +
  '> [!NOTE] Testo dell\'email\n' +
  '> ' + emailText.substring(0, 3000).replace(/\n/g, '\n> ') + '\n\n' +
  '---\n\n' +
  '## 🤖 Risposta Inviata\n' +
  aiResponse;

