  var fileName = (b.fileName || key).toLowerCase();
  var mimeType = b.mimeType || '';

  var isZip = fileName.endsWith('.zip') || mimeType === 'application/zip' || mimeType.includes('compressed');

  var fileItem = {
    json: {
      key: key,
      fileName: b.fileName || key,
      mimeType: b.mimeType,
      extension: fileName.split('.').pop(),
      isZip: isZip
    },
    binary: {}
  };
  fileItem.binary[key] = b;
  items.push(fileItem);
}

return items;

