var fileTexts = {};

items.forEach(item => {
  var data = item.json;
  var fileName = data.fileName || 'Allegato';
  var op = data.extractionOperation;

  if (!fileTexts[fileName]) {
    fileTexts[fileName] = {
      name: fileName,
      operation: op,
      textParts: [],
      rows: []
    };
  }

  if (data.text) {
    fileTexts[fileName].textParts.push(data.text);
  } else if (data.rowData) {
    fileTexts[fileName].rows.push(data.rowData);
  }
});

var attachmentTexts = [];
var hasPDF = false;

for (var fileName in fileTexts) {
  var fileInfo = fileTexts[fileName];
  var content = '';

  if (fileInfo.textParts.length > 0) {
    content = fileInfo.textParts.join('\n');
  } else if (fileInfo.rows.length > 0) {
    var rows = fileInfo.rows;
    var headers = Object.keys(rows[0] || {}).filter(k => k !== 'fileName' && k !== 'extractionOperation' && k !== 'key');

    var headerRow = '| ' + headers.join(' | ') + ' |';
    var separatorRow = '| ' + headers.map(() => '---').join(' | ') + ' |';
    var dataRows = rows.map(r => '| ' + headers.map(h => String(r[h] || '')).join(' | ') + ' |');

    content = [headerRow, separatorRow].concat(dataRows).join('\n');
  }

  if (content.trim().length > 10) {
    attachmentTexts.push('=== ALLEGATO: ' + fileName + ' ===\n' + content);
    if (fileInfo.operation === 'pdf') {
      hasPDF = true;
    }
  }
}

var attachmentText = attachmentTexts.join('\n\n---\n\n').substring(0, 10000);

return [{
