var ext = ($json.extension || '').toLowerCase();
var mime = ($json.mimeType || '').toLowerCase();
var op = 'text'; // default fallback

if (ext === 'pdf' || mime === 'application/pdf') {
  op = 'pdf';
} else if (ext === 'xlsx' || mime.includes('excel') || mime.includes('spreadsheet')) {
  op = 'xlsx';
} else if (ext === 'xls') {
  op = 'xls';
} else if (ext === 'ods') {
  op = 'ods';
} else if (ext === 'csv') {
  op = 'csv';
} else if (['docx', 'odt', 'txt', 'rtf', 'html', 'xml'].includes(ext)) {
  op = 'text';
} else if (['png', 'jpg', 'jpeg', 'gif', 'webp'].includes(ext) || mime.startsWith('image/')) {
  op = 'base64';
}

return {
  fileName: $json.fileName,
  key: $json.key,
  extension: ext,
  extractionOperation: op
};

